```python
def main():
    tasks = {}

    while True:
        print("To-Do List:")
        for task_name, is_completed in tasks.items():
            print(f"- {task_name} ({'Completed' if is_completed else 'Not Completed'})")

        action = input("\nEnter 'add' to add a task, 'remove' to remove a task, or 'completed' to mark a task as completed. Enter 'quit' to exit: ").lower()

        if action == 'add':
            task_name = input("Enter the task name: ")
            if task_name not in tasks:
                tasks[task_name] = False
                print(f"Added task: {task_name}")
            else:
                print(f"Task '{task_name}' already exists.")

        elif action == 'remove':
            task_name = input("Enter the task name to remove: ")
            if task_name in tasks:
                del tasks[task_name]
                print(f"Removed task: {task_name}")
            else:
                print(f"Task '{task_name}' does not exist.")

        elif action == 'completed':
            task_name = input("Enter the task name to mark as completed: ")
            if task_name in tasks:
                tasks[task_name] = not tasks[task_name]
                print(f"Marked task '{task_name}' as completed.")
            else:
                print(f"Task '{task_name}' does not exist.")

        elif action == 'quit':
            break
        else:
            print("Invalid action. Please try again.")

    print("Goodbye!")


if __name__ == "__main__":
    main()
```

This program will continuously prompt the user for actions until they enter 'quit'. Each action will update the tasks dictionary accordingly, and the program will print the updated to-do list after each action.
